#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, gzip, hashlib, json, os, shutil, subprocess, tempfile, urllib.request
from pathlib import Path

BLOB_SHA = "556aa6cdda1b4b9203dc66b97482b5f3f47e67a9"
BASE_SHA256 = "21f2d4a6f6aa72d18015961058edf9172dd4632320ce535f2ba01e034dc9a271"
V121_SHA256 = "1a44487de886d59f612cfbd083cacadf872ad56d0db13604cbf8af0056c600c2"
V130_SHA256 = "7a8e337b5651ba3bf0f805b588ba871ba1ad629f515e47bc4c42494862eacfa8"
PATCH_V121_GZ_B64 = ""
PATCH_V130_GZ_B64 = ""

def sha256(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()

def fetch_blob(repo: str, token: str | None) -> bytes:
    url = f"https://api.github.com/repos/{repo}/git/blobs/{BLOB_SHA}"
    headers = {"Accept":"application/vnd.github+json", "X-GitHub-Api-Version":"2022-11-28", "User-Agent":"kaggriculture-v130-rebuilder"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=60) as r:
        payload = json.load(r)
    if payload.get("encoding") != "base64":
        raise RuntimeError(f"unexpected blob encoding: {payload.get('encoding')!r}")
    return base64.b64decode(payload["content"])

def patch_bytes(encoded: str) -> bytes:
    return gzip.decompress(base64.b64decode(encoded))

def apply_patch(target: Path, encoded: str) -> None:
    with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as f:
        f.write(patch_bytes(encoded)); name=f.name
    try:
        subprocess.run(["patch", "--batch", "--silent", str(target), name], check=True)
    finally:
        try: os.unlink(name)
        except OSError: pass

def main() -> int:
    ap=argparse.ArgumentParser()
    ap.add_argument("--repo", default="giyogiyogiyo929929929-gif/kaggriculture-il")
    ap.add_argument("--token", default=os.environ.get("GITHUB_TOKEN"))
    ap.add_argument("--out-dir", default="eval_agents/v130")
    ap.add_argument("--base-file")
    args=ap.parse_args()
    out=Path(args.out_dir); out.mkdir(parents=True, exist_ok=True)
    base=out/"base_blob.py"; v121=out/"v121_champion_same_turn_unwind.py"; v130=out/"v130_candidate_late_town_draw_gate24.py"
    raw=Path(args.base_file).read_bytes() if args.base_file else fetch_blob(args.repo,args.token)
    base.write_bytes(raw)
    if sha256(base)!=BASE_SHA256: raise RuntimeError(f"base sha256 mismatch: {sha256(base)}")
    shutil.copyfile(base,v121); apply_patch(v121,PATCH_V121_GZ_B64)
    if sha256(v121)!=V121_SHA256: raise RuntimeError(f"v121 sha256 mismatch: {sha256(v121)}")
    shutil.copyfile(v121,v130); apply_patch(v130,PATCH_V130_GZ_B64)
    if sha256(v130)!=V130_SHA256: raise RuntimeError(f"v130 sha256 mismatch: {sha256(v130)}")
    compile(v121.read_text(encoding="utf-8"),str(v121),"exec")
    compile(v130.read_text(encoding="utf-8"),str(v130),"exec")
    print(json.dumps({"base_blob":BLOB_SHA,"base_sha256":BASE_SHA256,"v121_sha256":V121_SHA256,"v130_sha256":V130_SHA256,"out_dir":str(out)},indent=2))
    return 0
if __name__=="__main__": raise SystemExit(main())
